local create_native_contract=(function()
-- Discover once from semantic code contracts; never call a scanned function here.
return function(api, recipes, validate)
    if not api then
        local ffi = require('ffi')
        ffi.cdef[[
            void * __stdcall GetModuleHandleA(const char *);
            void * __stdcall GetCurrentProcess(void);
            int __stdcall ReadProcessMemory(void *, const void *, void *, size_t, size_t *);
        ]]
        local process, buffer, copied = ffi.C.GetCurrentProcess(), ffi.new('uint8_t[65536]'), ffi.new('size_t[1]')
        api = {
            module=function(name) return tonumber(ffi.cast('uintptr_t',ffi.C.GetModuleHandleA(name))) end,
            address=function(world)
                assert(type(world) == 'userdata', 'unsupported world')
                return tonumber(ffi.cast('uintptr_t',world))
            end,
            read=function(at,size)
                assert(type(at) == 'number' and at >= 65536 and at % 1 == 0 and at+size < 2^47 and
                    size > 0 and size <= 65536, 'invalid read range')
                copied[0] = 0
                if ffi.C.ReadProcessMemory(process,ffi.cast('const void *',at),buffer,size,copied) ~= 0 and
                    tonumber(copied[0]) == size then return ffi.string(buffer,size) end
            end
        }
    end
    local cached, failure, attempted
    local function read(at, size)
        local data = api.read(at,size)
        assert(type(data) == 'string' and #data == size, 'unavailable contract memory')
        return data
    end
    local function u32(data, at)
        local a,b,c,d = data:byte(at+1,at+4)
        return a+b*256+c*65536+d*16777216
    end
    local function module(base)
        local dos = read(base,64)
        assert(dos:sub(1,2) == 'MZ', 'invalid module header')
        local pe_at = u32(dos,0x3c)
        assert(pe_at >= 64 and pe_at < 1048576, 'invalid PE offset')
        local pe = read(base+pe_at,0x58)
        local count = pe:byte(7)+pe:byte(8)*256
        local optional = pe:byte(21)+pe:byte(22)*256
        local size = u32(pe,0x50)
        assert(pe:sub(1,4) == 'PE\0\0' and pe:byte(5) == 0x64 and pe:byte(6) == 0x86 and
            pe:byte(25) == 0x0b and pe:byte(26) == 2 and count > 0 and count <= 96 and
            optional >= 0xf0 and optional <= 1024 and size > 4096 and size <= 536870912 and
            base+size < 2^47 and pe_at+24+optional+count*40 <= size, 'invalid PE sections')
        local sections, table_bytes = {}, read(base+pe_at+24+optional,count*40)
        for i=0,count-1 do
            local rva, length, flags = u32(table_bytes,i*40+12),u32(table_bytes,i*40+8),u32(table_bytes,i*40+36)
            assert(rva >= 4096 and length > 0 and rva+length <= size, 'invalid section range')
            sections[#sections+1] = {first=base+rva,last=base+rva+length,
                code=math.floor(flags/0x20000000)%2 == 1, writable=math.floor(flags/0x80000000)%2 == 1}
        end
        return {base=base,size=size,stamp=u32(pe,8),sections=sections}
    end
    local function contains(mod, at, size, kind)
        for _, section in ipairs(mod.sections) do
            if at >= section.first and at+size <= section.last then
                return kind == 'code' and section.code or kind ~= 'code' and not section.code and
                    (kind ~= 'global' or section.writable)
            end
        end
        return false
    end
    local function extract(recipe, bytes, at, mod)
        local fields = {address=at}
        for _, field in ipairs(recipe.fields) do
            local value = u32(bytes,field[2])
            if field[4] ~= 'offset' then
                if value >= 2147483648 then value = value-4294967296 end
                value = at+field[3]+value
                assert(contains(mod,value,field[4] == 'global' and 8 or 1,field[4]), recipe.name..' target outside '..field[4])
            else
                assert(value > 0 and value < 16777216, recipe.name..' object offset out of range')
            end
            fields[field[1]] = value
        end
        return fields
    end
    local function discover(exe, game)
        local modules = {['helldivers2.exe']=module(exe),['game.dll']=module(game)}
        local found, selected = {}, {}
        for _, recipe in ipairs(recipes) do found[recipe.name] = {} end
        for name, mod in pairs(modules) do
            local subset, overlap = {}, 0
            for _, recipe in ipairs(recipes) do
                if recipe.module == name then subset[#subset+1] = recipe; overlap = math.max(overlap,recipe.size-1) end
            end
            local fast = #subset > 0
            for _, recipe in ipairs(subset) do
                for _, hint in ipairs(recipe.hints or {}) do
                    if mod.stamp == hint[1] and mod.size == hint[2] and contains(mod,mod.base+hint[3],recipe.size,'code') then
                        local bytes, matches = read(mod.base+hint[3],recipe.size), true
                        for _, piece in ipairs(recipe.pieces) do
                            if bytes:sub(piece[1]+1,piece[1]+#piece[2]) ~= piece[2] then matches = false; break end
                        end
                        if matches then found[recipe.name] = {{address=mod.base+hint[3],bytes=bytes}} end
                        break
                    end
                end
                if #found[recipe.name] == 0 then fast = false end
            end
            if not fast and #subset > 0 then
            for _, recipe in ipairs(subset) do found[recipe.name] = {} end
            for _, section in ipairs(mod.sections) do
                if section.code then
                    local tail = ''
                    for cursor=section.first,section.last-1,65536 do
                        local bytes = tail..read(cursor,math.min(65536,section.last-cursor))
                        local start = cursor-#tail
                        for _, recipe in ipairs(subset) do
                            local pos = 1
                            while true do
                                pos = bytes:find(recipe.anchor,pos,true)
                                if not pos then break end
                                local at, matches = pos-recipe.anchor_offset, true
                                if at >= 1 and at+recipe.size-1 <= #bytes and start+at+recipe.size-1 > cursor then
                                    for _, piece in ipairs(recipe.pieces) do
                                        if bytes:sub(at+piece[1],at+piece[1]+#piece[2]-1) ~= piece[2] then matches = false; break end
                                    end
                                    if matches then
                                        local rows = found[recipe.name]
                                        assert(#rows < 2, 'ambiguous '..recipe.name)
                                        rows[#rows+1] = {address=start+at-1,bytes=bytes:sub(at,at+recipe.size-1)}
                                    end
                                end
                                pos = pos+1
                            end
                        end
                        tail = bytes:sub(math.max(1,#bytes-overlap+1))
                    end
                end
            end
        end
        end
        for _, recipe in ipairs(recipes) do
            assert(#found[recipe.name] == 1, (#found[recipe.name] == 0 and 'missing ' or 'ambiguous ')..recipe.name)
            local row = found[recipe.name][1]
            selected[recipe.name] = extract(recipe,row.bytes,row.address,modules[recipe.module])
        end
        return validate(selected,read,u32,modules)
    end
    return function()
        if attempted then return cached,failure end
        local exe, game = api.module('helldivers2.exe'),api.module('game.dll')
        if not exe or not game or exe < 65536 or game < 65536 then return nil,'native modules unavailable' end
        attempted = true
        local ok, result = pcall(discover,exe,game)
        if ok then cached = result else failure = tostring(result) end
        return cached,failure
    end, api
end

end)()
