local read_live_grenades=(function()
-- Read-only Throwable + Explosive snapshots. No native game functions are called.
return function(api, resolve_native, resolve_grenade)
    local ffi, bit = require('ffi'), require('bit')
    local core, layout, cached_world, cached_em, cached_pool, configs, radii, mortar_types, mortar_motion
    local scalar = ffi.new('float[3]')
    local function read(at, size)
        assert(type(at) == 'number' and at >= 65536 and at+size < 2^47 and at%1 == 0 and
            size > 0 and size <= 65536, 'invalid grenade read')
        local bytes = api.read(at,size)
        assert(type(bytes) == 'string' and #bytes == size, 'grenade memory unavailable')
        return bytes
    end
    local function u32(bytes, at)
        local a,b,c,d = bytes:byte(at+1,at+4)
        return a+b*256+c*65536+d*16777216
    end
    local function pointer(bytes, at)
        at = at or 0
        local value = u32(bytes,at)+u32(bytes,at+4)*4294967296
        assert(value >= 65536 and value < 2^47, 'invalid grenade pointer')
        return value
    end
    local function ptr(at) return pointer(read(at,8)) end
    local function number(bytes, at)
        ffi.copy(scalar,bytes:sub(at+1,at+4),4)
        local value = tonumber(scalar[0])
        assert(value > -math.huge and value < math.huge, 'invalid grenade float')
        return value
    end
    local function lookup(header, at, key)
        local capacity, empty, multiplier = u32(header,at+8),u32(header,at+12),u32(header,at+16)
        if capacity == 0 or key == empty then return end
        assert(capacity <= 1048576 and bit.band(capacity,capacity-1) == 0, 'invalid grenade map')
        local slots = pointer(header,at)
        local hash = tonumber(ffi.cast('uint32_t',ffi.new('uint64_t',key)*multiplier))
        for probe=0,math.min(capacity,128)-1 do
            local row = read(slots+bit.band(hash+probe,capacity-1)*8,8)
            if u32(row,0) == key then return u32(row,4) ~= 0xffffffff and u32(row,4) or nil end
            if u32(row,0) == empty then return end
        end
        error('grenade map probe limit')
    end
    local function blast_radius(kind)
        if kind == 0 then return 0 end
        assert(kind < 0x1a7, 'invalid grenade explosion type')
        if radii[kind] ~= nil then return radii[kind] end
        local info = read(ptr(core.game+layout.explosion_info+kind*8),28)
        assert(u32(info,0) == kind, 'grenade explosion row changed')
        local damage, radius = u32(info,4),number(info,20)
        assert(radius >= 0 and radius <= 1000 and damage < 4096, 'invalid grenade blast data')
        if damage == 0 then radius = 0 else
            local row = read(ptr(core.game+layout.damage+damage*8),12)
            assert(u32(row,0) == damage, 'grenade damage row changed')
            if u32(row,4) == 0 and u32(row,8) == 0 then radius = 0 end
        end
