        local world, pool = ptr(world_address),ptr(core.game+core.pool)
        assert(ptr(pool) == world, 'grenade world mismatch')
        local em = ptr(core.game+core.em)
        if cached_world ~= world or cached_em ~= em or cached_pool ~= pool then
            cached_world,cached_em,configs,radii,mortar_types = world,em,{},{},{[0]=false}
            cached_pool,mortar_motion = pool,{}
