                        mortar_types[kind] = ((u32(settings,4) == 900451699 and u32(settings,8) == 2679866361) or
                            (u32(settings,4) == 1039435686 and u32(settings,8) == 1650235156) or
                            (u32(settings,4) == 2277522391 and u32(settings,8) == 341705628)) and
                            ((u32(settings,128) == 0x185b6567 and u32(settings,132) == 0xa6cd8a90) or
                            (u32(settings,128) == 0xf3d77d11 and u32(settings,132) == 0xec5caf6d))
