                            if previous and previous.kind == kind then
                                local x,y,z = position[1]-previous.position[1],position[2]-previous.position[2],position[3]-previous.position[3]
                                if x*x+y*y+z*z > .0001 then previous = nil end
                            else previous = nil end
                            motion[slot] = previous or {kind=kind,position=position,still=0}
                            if previous then previous.still = math.min(.25,previous.still+(dt or 0)) end
                            if motion[slot].still < .25 then mortars[#mortars+1] = {position=position} end
                        end
                    end
                end
            end
            assert(ptr(core.game+core.pool) == pool and ptr(pool) == world, 'mortar pool changed')
        end
        mortar_motion = motion
        local manager = ptr(core.game+layout.throwable)
        local header = read(manager,0x68)
        local count = u32(header,0x1c)
        assert(count <= u32(header,0x10) and count <= 4096, 'invalid grenade count')
        if count == 0 then return {mortars=mortars} end
        local owners, states = pointer(header,0x48),pointer(header,0x60)
        local explosives = ptr(core.game+layout.explosive)
        local explosive_header = read(explosives,0xc0)
        local explosive_count = u32(explosive_header,0x24)
        assert(explosive_count <= u32(explosive_header,0x18) and explosive_count <= 262144,
            'invalid explosive count')
        local registry = ptr(core.exe+core.registry)
        local units = read(registry,0xa8)
        local generations, objects, unit_count = pointer(units,0xa0),pointer(units,0x88),u32(units,0x98)
        local result = {mortars=mortars}
        for first=0,count-1,512 do
            local amount = math.min(512,count-first)
            local owner_bytes, state_bytes = read(owners+first*8,amount*8),read(states+first*0x2c,amount*0x2c)
            for i=0,amount-1 do
                if state_bytes:byte(i*0x2c+1) == 1 and state_bytes:byte(i*0x2c+2) == 1 then
                    local ok, row = pcall(function()
                        local index = first+i
                        local owner = pointer(owner_bytes,i*8)
                        local record = read(owner,24)
                        local ref, handle = u32(record,8),u32(record,12)
                        local explosive_index = lookup(explosive_header,0x38,ref)
                        if not explosive_index then return end
                        assert(explosive_index < explosive_count and
                            ptr(pointer(explosive_header,0x50)+explosive_index*8) == owner, 'grenade explosive owner changed')
                        local explosion_state = pointer(explosive_header,0x68)+explosive_index*0x38
                        if read(explosion_state+1,1):byte() ~= 0 then return end
                        local override = lookup(explosive_header,0x78,ref)
                        local settings
                        if override then
                            assert(override < u32(explosive_header,0xb0), 'invalid grenade override')
                            settings = pointer(explosive_header,0xb8)+override*0x168
                        else
                            local resource = record:sub(1,8)
                            settings = configs[resource]
                            if settings == nil then
                                local table_at = ptr(em+layout.explosive_table)
                                local slots = read(table_at,0x8e0)
                                settings = false
                                for n=0,141 do
                                    if slots:sub(n*16+1,n*16+8) == resource then
                                        local slot = u32(slots,n*16+8)
                                        assert(slot < 142, 'invalid grenade config row')
                                        settings = table_at+0x8e0+slot*0x168
                                        break
                                    end
                                end
                                configs[resource] = settings
                            end
                        end
                        if not settings then return end
                        local radius = blast_radius(u32(read(settings+0x24,4),0))
                        if radius <= 0 then return end
                        local slot, generation = bit.band(handle,0x3fffff),bit.rshift(handle,22)
                        assert(slot < unit_count and read(generations+slot,1):byte() == generation, 'stale grenade unit')
                        local object = ptr(objects+slot*8)
                        assert(ptr(ptr(object)+0xe8) == core.exe+core.scene, 'grenade scene layout changed')
                        local xyz = read(ptr(object+0x88)+0x30,12)
                        local position = {number(xyz,0),number(xyz,4),number(xyz,8)}
                        assert(read(owner,24) == record and ptr(owners+index*8) == owner and
                            read(states+index*0x2c,2) == string.char(1,1) and
                            read(explosion_state+1,1):byte() == 0 and
                            ptr(pointer(explosive_header,0x50)+explosive_index*8) == owner and
                            read(generations+slot,1):byte() == generation and ptr(objects+slot*8) == object,
                            'grenade changed during copy')
