                    end)
                    if ok and row then result[#result+1] = row end
                end
            end
        end
        local latest = read(manager,0x68)
        assert(ptr(core.game+layout.throwable) == manager and u32(latest,0x1c) == count and
            pointer(latest,0x48) == owners and pointer(latest,0x60) == states and
            ptr(core.game+layout.explosive) == explosives and
            read(explosives+0x50,0x20) == explosive_header:sub(0x51,0x70) and
            ptr(core.exe+core.registry) == registry and ptr(core.game+core.em) == em and
            ptr(core.game+core.pool) == pool and ptr(pool) == world and ptr(world_address) == world,
            'grenade world or component storage changed')
