local draw_live_grenades=(function()
-- Private render-only volumes: depth-tested dots or shade on live hazards and predicted damage areas.
return function(read_grenades, ground_hit)
    local world, spheres, drop_line = nil, {}, nil
    local function live(sr, target)
        if not target then return false end
        local ok, worlds = pcall(sr and sr.Application and sr.Application.worlds)
        if ok and type(worlds) == 'table' then
            for _, candidate in pairs(worlds) do if candidate == target then return true end end
            return false
        end
    end
    local function discard(sr, index)
        local shell = spheres[index]
