                    sr.LineObject.reset(drop_line)
                    local saved = sr.Script.temp_byte_count()
                    local zero = sr.Vector3(0,0,0)
                    sr.LineObject.add_line(drop_line, sr.Color(0,0,0,0), zero, zero)
                    sr.LineObject.dispatch(world, drop_line)
                    sr.Script.set_temp_byte_count(saved)
                    sr.World.destroy_line_object(world, drop_line); drop_line = nil
                end
