        local grenades, mortars = {}, {}
        if state.config.live_damage then
            local snapshot = assert(read_grenades(sr, state, dt), 'grenades unavailable')
            mortars = snapshot.mortars or mortars
            for _, grenade in ipairs(snapshot) do
                grenades[#grenades+1] = grenade
            end
        end
        if state.config.enabled and state.config.damage_ring == 's' then
            if state.damage_volume then grenades[#grenades+1] = state.damage_volume end
            for _, player in pairs(state.players or {}) do
                if player.damage_volume then grenades[#grenades+1] = player.damage_volume end
            end
        end
        if #grenades == 0 and #mortars == 0 then release(sr); return end
        world = state.world
        if drop_line then sr.LineObject.reset(drop_line) end
        if #mortars > 0 and ground_hit and state.local_tp and sr.Unit.alive(state.local_tp) then
            if not drop_line then drop_line = assert(sr.World.create_line_object(world, false)) end
