        local fx, fy, fz = sr.Vector3.x(forward), sr.Vector3.y(forward), sr.Vector3.z(forward)
        local rx, ry, rz = sr.Vector3.x(right), sr.Vector3.y(right), sr.Vector3.z(right)
        local ux, uy, uz = sr.Vector3.x(up), sr.Vector3.y(up), sr.Vector3.z(up)
        local ax, ay, az = sr.Vector3.x(a), sr.Vector3.y(a), sr.Vector3.z(a)
        local bx, by, bz = sr.Vector3.x(b), sr.Vector3.y(b), sr.Vector3.z(b)
        local da = (ax-ox)*fx+(ay-oy)*fy+(az-oz)*fz
        local db = (bx-ox)*fx+(by-oy)*fy+(bz-oz)*fz
        if da <= .1 and db <= .1 then return end
        if da < .1 then
            local t = (.1-da)/(db-da)
            ax, ay, az, da = ax+t*(bx-ax), ay+t*(by-ay), az+t*(bz-az), .1
        elseif db < .1 then
            local t = (.1-db)/(da-db)
            bx, by, bz, db = bx+t*(ax-bx), by+t*(ay-by), bz+t*(az-bz), .1
        end
        local focal = state.compat_height/(2*math.tan((state.compat_fov or 55)*math.pi/360))
        local function project(x,y,z,depth)
            local dx,dy,dz = x-ox,y-oy,z-oz
            return state.compat_width*.5+(dx*rx+dy*ry+dz*rz)*focal/depth,
                state.compat_height*.5+(dx*ux+dy*uy+dz*uz)*focal/depth
        end
        local x1,y1 = project(ax,ay,az,da)
        local x2,y2 = project(bx,by,bz,db)
        local distance = math.sqrt((x2-x1)^2+(y2-y1)^2)
        if distance >= math.huge then return end
        local steps = math.max(1,math.min(64,math.ceil(distance/2)))
        local dots = state.compat_points
        if not dots then dots = {}; state.compat_points = dots end
        for i=0,steps do
            if state.compat_num >= 768 then break end
            local t = i/steps
            local x,y = x1+(x2-x1)*t,y1+(y2-y1)*t
            if x >= 0 and y >= 0 and x < state.compat_width and y < state.compat_height then
                local index = state.compat_num + 1
                local dot = dots[index] or {}
                dot.x, dot.y = x, y
                dot.wx, dot.wy, dot.wz = ax+(bx-ax)*t, ay+(by-ay)*t, az+(bz-az)*t
                dot.color = color
                dots[index], state.compat_num = dot, index
            end
        end
    end

    local function compat_flush(sr, state)
        local n = state.compat_num or 0
        if n == 0 or not state.compat_gui or state.compat_failed then return end
        local dots = state.compat_points
        local bins = math.min(32, math.max(1, math.ceil(n/24)))
        local visible
        local pose = state.compat_camera
        if state.is_local ~= false and state.compat_native_query and pose then
            local eye, forward = sr.Matrix4x4.translation(pose), sr.Matrix4x4.forward(pose)
            local ox, oy, oz = sr.Vector3.x(eye), sr.Vector3.y(eye), sr.Vector3.z(eye)
            local fx, fy, fz = sr.Vector3.x(forward), sr.Vector3.y(forward), sr.Vector3.z(forward)
            local first, middle, last = dots[1], dots[math.floor((n+1)/2)], dots[n]
            local cache = state.compat_occlusion_cache
            local draw_index = state.compat_draw_index or 0
            local function close(a,b,limit) return math.abs(a-b) <= limit end
            local function near(a,b)
                return close(a.wx,b.wx,.25) and close(a.wy,b.wy,.25) and close(a.wz,b.wz,.25)
            end
            if cache and cache.bins == bins and cache.n == n and
                draw_index-cache.index >= 0 and draw_index-cache.index <= 3 and
                close(ox,cache.ox,.2) and close(oy,cache.oy,.2) and close(oz,cache.oz,.2) and
                fx*cache.fx+fy*cache.fy+fz*cache.fz >= .9996 and
                near(first,cache.first) and near(middle,cache.middle) and near(last,cache.last) then
                visible = cache.visible
            else
                local checked = {}
                local valid = true
                for bin=1,bins do
                    local index = math.min(n,math.max(1,math.floor((bin-.5)*n/bins)+1))
                    local dot = dots[index]
                    local ok, blocked, reason = pcall(compat_native_cast, sr, state,
                        ox, oy, oz, dot.wx, dot.wy, dot.wz)
                    if not ok or type(blocked) ~= 'boolean' then
                        valid = false
                        state.compat_native_query = nil
                        state.compat_occlusion_cache = nil
                        compat_log(state, 'NATIVE_CAST_UNAVAILABLE:' .. tostring(reason or blocked))
                        break
                    end
                    checked[bin] = not blocked
                end
                if valid then
                    visible = checked
                    state.compat_occlusion_cache = {
                        bins=bins,n=n,index=draw_index,ox=ox,oy=oy,oz=oz,fx=fx,fy=fy,fz=fz,
                        first={wx=first.wx,wy=first.wy,wz=first.wz},
                        middle={wx=middle.wx,wy=middle.wy,wz=middle.wz},
                        last={wx=last.wx,wy=last.wy,wz=last.wz},visible=checked}
                    compat_log(state, 'NATIVE_QUERY_ACTIVE')
                end
            end
        elseif state.is_local ~= false then
            state.compat_occlusion_cache = nil
            compat_log(state, 'NATIVE_QUERY_UNAVAILABLE:' .. tostring(state.ground_status))
        end
        local drawn = 0
        local ok = pcall(function()
            for i=1,n do
                local bin = math.min(bins,math.floor((i-1)*bins/n)+1)
                if not visible or visible[bin] then
                    local dot = dots[i]
                    sr.Gui.rect(state.compat_gui, sr.Vector3(dot.x-.75,dot.y-.75,900),
                        sr.Vector2(1.5,1.5),dot.color)
                    drawn = drawn + 1
                end
            end
        end)
        if not ok then state.compat_failed = true end
        state.compat_count = drawn
    end

    local function live(sr, state)
        if not state.world then return false end
        local ok, worlds = pcall(sr.Application and sr.Application.worlds)
        if ok and type(worlds) == 'table' then
            for _, world in pairs(worlds) do if world == state.world then return true end end
        end
        return false
    end

    local function hide(sr, state)
        state.damage_volume = nil
        for _, key in ipairs({'line', 'hit_line'}) do
            if state[key] and live(sr, state) then
                sr.LineObject.reset(state[key])
                -- Replace submitted geometry without relying on empty batches or destruction.
                local point = sr.Vector3(0, 0, 0)
                sr.LineObject.add_line(state[key], sr.Color(0, 0, 0, 0), point, point)
                sr.LineObject.dispatch(state.world, state[key])
            end
        end
    end

    local function release(sr, state)
        if (state.line or state.hit_line) and live(sr, state) then
            hide(sr, state)
            for _, key in ipairs({'line', 'hit_line'}) do
                if state[key] then sr.World.destroy_line_object(state.world, state[key]) end
            end
        end
        if state.label_gui and live(sr, state) then sr.World.destroy_gui(state.world, state.label_gui) end
        if state.compat_gui and state.compat_world then
            pcall(sr.World.destroy_gui, state.compat_world, state.compat_gui)
        end
        state.line, state.hit_line, state.label_gui, state.compat_gui, state.compat_camera, state.compat_world = nil, nil, nil, nil, nil, nil
        state.guide_visible = false
        state.compat_native_query, state.compat_occlusion_cache = nil, nil
    end

    local function unique(sr, state, resource, player_index)
        local unit, count = nil, 0
        for _, candidate in pairs(sr.World.units_by_resource(state.world, resource) or {}) do
            if sr.Unit.alive(candidate) and (player_index == nil or
                (sr.Unit.has_animation_state_machine(candidate) and
                sr.Unit.animation_has_variable(candidate, 'player_number') and
                sr.Unit.animation_get_variable(candidate,
                    sr.Unit.animation_find_variable(candidate, 'player_number')) == player_index)) then
                unit, count = candidate, count + 1
            end
        end
        return count == 1 and unit or nil
    end

    local function resolve(sr, state, dt)
        -- Reset staging lines; hide() submits a replacement when drawing stops.
        for _, key in ipairs({'line', 'hit_line'}) do
            if state[key] and live(sr, state) then sr.LineObject.reset(state[key]) end
        end
        local world, session = sr.Application.main_world(), sr.Network.game_session()
        if state.world ~= world or state.session ~= session then
            release(sr, state)
            for key in pairs(state) do state[key] = nil end
            state.world, state.session, state.elapsed = world, session, 1
        end
        if not world or not live(sr, state) then state.position, state.velocity = nil, nil; return nil, 'NO_LIVE_WORLD' end
        local valid_dt = type(dt) == 'number' and dt > 0 and dt < math.huge
        state.elapsed = state.elapsed + (valid_dt and dt or 1 / 60)
        if state.elapsed >= 1 then
            -- Resolve the peer's player index when several third-person rigs are present.
            state.tp, state.fp = nil, nil
            state.tp = unique(sr, state, 'content/fac_helldivers/cha_avatar/avatar_helldiver')
            if (not state.tp or state.player_index ~= nil) and session then
                state.tp = nil
                local peer, player = sr.Network.peer_id(), nil
                for _, id in pairs(peer and sr.GameSession.objects_owned_by(session, peer) or {}) do
                    if sr.GameSession.game_object_exists(session, id) and
                        sr.GameSession.game_object_is_type(session, id, 'un6y1d') then
                        if player and player ~= id then player = false; break end
                        player = id
                    end
                end
                if player then
                    for _, field in pairs(sr.Network.object_info('un6y1d').fields) do
                        if tostring(field.id):lower():gsub('^0x', '') == 'b03b8bce' then
                            local index = sr.GameSession.game_object_field(session, player, 'index')
                            if type(index) == 'number' and index >= 0 and index < math.huge and index % 1 == 0 then
                                state.player_index = index
                                state.tp = unique(sr, state, 'content/fac_helldivers/cha_avatar/avatar_helldiver', index)
                            end
                            break
                        end
                    end
                end
            end
            state.fp = unique(sr, state, 'content/fac_helldivers/fp_cha_avatar/fp_cha_avatar')
            state.elapsed = 0
        end
        return true
    end

    local function draw_surface_hit(sr, state, hit, color, radius, dotted)
        if not radius and state.config and state.config.landing_marker == false then return end
        if type(hit) ~= 'table' or type(hit.position) ~= 'table' or type(hit.normal) ~= 'table' then return end
        local p, n = hit.position, hit.normal
        for axis = 1, 3 do
            if type(p[axis]) ~= 'number' or not (p[axis] > -math.huge and p[axis] < math.huge) or
                type(n[axis]) ~= 'number' or not (n[axis] > -math.huge and n[axis] < math.huge) then return end
        end
        local nx, ny, nz = unpack(n)
        local length = math.sqrt(nx*nx+ny*ny+nz*nz)
        if length <= 1e-8 or length >= math.huge then return end
        if not state.hit_line then state.hit_line = assert(sr.World.create_line_object(state.world, true)) end
        nx, ny, nz = nx/length, ny/length, nz/length
        if radius and not dotted then nx, ny, nz = 0, 0, 1 end
        local tx, ty, tz = ny, -nx, 0
        if math.abs(nz) > .9 then tx, ty, tz = 0, nz, -ny end
        length = math.sqrt(tx*tx+ty*ty+tz*tz)
        tx, ty, tz = tx/length, ty/length, tz/length
        local bx, by, bz = ny*tz-nz*ty, nz*tx-nx*tz, nx*ty-ny*tx
        -- Lift 5 mm along the drawing normal to avoid coplanar flicker.
        local px, py, pz = p[1]+.005*nx, p[2]+.005*ny, p[3]+.005*nz
        if not radius and state.config and state.config.landing_marker == 'x' then
            local scale = .12/math.sqrt(2)
            for sign = -1, 1, 2 do
                local x, y, z = scale*(tx+sign*bx), scale*(ty+sign*by), scale*(tz+sign*bz)
                add_compat_line(sr, state, 'hit_line', color, sr.Vector3(px-x, py-y, pz-z),
                    sr.Vector3(px+x, py+y, pz+z))
            end
            return
        end
        local dot = not radius and state.config and state.config.landing_marker == '.'
        dotted = dotted or radius and state.config and (state.config.damage_ring == '.' or state.config.damage_ring == 's')
        local segments = dot and 12 or radius and 64 or 24
        radius = radius or (dot and .04 or .12)
        local previous = not dotted and sr.Vector3(px+radius*tx, py+radius*ty, pz+radius*tz)
        for i = 1, segments do
            local angle = i*(dot and math.pi or 2*math.pi)/segments
            local x, y = radius*math.cos(angle), radius*math.sin(angle)
            local point = sr.Vector3(px+x*tx+y*bx, py+x*ty+y*by, pz+x*tz+y*bz)
            if dot then
                previous = sr.Vector3(px-x*tx-y*bx, py-x*ty-y*by, pz-x*tz-y*bz)
            elseif dotted then
                angle = angle-2*math.pi/(segments*8)
                x, y = radius*math.cos(angle), radius*math.sin(angle)
                previous = sr.Vector3(px+x*tx+y*bx, py+x*ty+y*by, pz+x*tz+y*bz)
            end
            add_compat_line(sr, state, 'hit_line', color, previous, point)
            previous = point
        end
    end

    local function render(sr, state, dt)
        local world, session = state.world, state.session
        local valid_dt = type(dt) == 'number' and dt > 0 and dt < math.huge
        local reason = not valid_dt and 'INVALID_DT' or not state.tp and 'NO_LOCAL_TP' or not state.fp and 'NO_FP' or
            (not sr.Unit.alive(state.tp) or not sr.Unit.alive(state.fp)) and 'DEAD_RIG' or
            not state.emplacement_model and (not sr.Unit.has_animation_state_machine(state.tp) or not sr.Unit.has_animation_state_machine(state.fp) or
            not sr.Unit.animation_has_variable(state.fp, 'weapon_selected')) and 'ANIMATION_UNAVAILABLE'
        if reason then
            state.position, state.velocity = nil, nil; return nil, reason
        end
        local unit, model, rig, weapon_reason = state.tp, state.emplacement_model, state.tp
        if model and (model.name == 'E/AT-12' or model.name == 'E/GL-21') and not state.occupant then
            return nil, 'EMPLACEMENT_UNOCCUPIED'
        end
        if model and model.exo_launcher and (not state.occupant or not state.exo_launch) then return nil, 'EXO_NOT_LOADED' end
        if model and model.attached_resource then
            assert(sr.Unit.has_node(unit, model.attachment_node), 'missing mounted weapon attachment')
            local anchor = sr.Unit.world_position(unit, sr.Unit.node(unit, model.attachment_node))
            unit, weapon_reason = nil, 'NO_MOUNT_MATCH'
            for _, candidate in pairs(sr.World.units_by_resource(world, model.attached_resource) or {}) do
                if sr.Unit.alive(candidate) and sr.Vector3.distance(anchor, sr.Unit.world_position(candidate, 1)) == 0 then
                    assert(not unit or unit == candidate, 'ambiguous mounted weapon')
                    unit = candidate
                end
            end
        end
        if not model then
            local grip = sr.Unit.animation_get_variable(state.fp, sr.Unit.animation_find_variable(state.fp, 'weapon_selected'))
            if coordinated then
                unit, model, rig, weapon_reason = select_weapon(sr, world, session, state.tp, state.fp, grip, dt,
                    state.draw_all or false, state.scope, state.frame, state.config and state.config.damage_ring)
            else
                unit, model, rig, weapon_reason = select_weapon(sr, world, session, state.tp, state.fp, grip, dt,
                    nil, nil, nil, state.config and state.config.damage_ring)
            end
        end
        if not unit then state.position, state.velocity = nil, nil; return nil, 'WEAPON:' .. tostring(weapon_reason) end
        if state.motion_unit ~= unit or state.motion_rig ~= rig or (state.motion_model ~= model and
            (not (model.charge_time_s or model.damage_charge_time_s or model.ammo_damage_radii) or state.motion_model.resource ~= model.resource or state.motion_model.muzzle ~= model.muzzle)) then
            state.position = nil
        end
        state.motion_unit, state.motion_model, state.motion_rig = unit, model, rig
        -- Track avatar movement for throws; the shoulder also moves with the throw animation.
        assert(sr.Unit.has_node(unit, model.muzzle), 'missing muzzle node')
        local muzzle = sr.Unit.world_position(unit, sr.Unit.node(unit, model.muzzle))
        local position = {sr.Vector3.x(muzzle), sr.Vector3.y(muzzle), sr.Vector3.z(muzzle)}
        local motion_position = position
        if model.throwable then
            local root = sr.Unit.world_position(state.tp, 1)
            motion_position = {sr.Vector3.x(root), sr.Vector3.y(root), sr.Vector3.z(root)}
        end
        state.velocity = {0, 0, 0}
        for axis = 1, 3 do
            assert(type(position[axis]) == 'number' and position[axis] > -math.huge and position[axis] < math.huge,
                'invalid muzzle position')
            assert(type(motion_position[axis]) == 'number' and motion_position[axis] > -math.huge and motion_position[axis] < math.huge,
                'invalid movement position')
            state.velocity[axis] = state.position and state.motion_position and (motion_position[axis] - state.motion_position[axis]) / dt or 0
            assert(state.velocity[axis] > -math.huge and state.velocity[axis] < math.huge, 'invalid movement velocity')
        end
        state.position, state.motion_position = position, motion_position
        if state.config and not state.config.enabled then return nil, 'DISABLED' end
        if state.config and state.config.weapons[model.name] == false then return nil, 'WEAPON_DISABLED:' .. model.name end
        if model.throwable and state.is_local == false then return nil, 'THROW_LOCAL_ONLY' end
        -- animation_get_state returns layer states only: raw layer24 is tuple item25, with no seed.
        local animation_states = not model.exo_launcher and (not model.emplacement or state.occupant) and
            {sr.Unit.animation_get_state(state.occupant or state.tp)} or nil
        local layer, override = animation_states and animation_states[25], animation_states and animation_states[19]
        local mount_ready = model.exo_launcher or not state.occupant or animation_states[14] == (model.name == 'E/GL-21' and 27 or 21)
        -- Layer18 has directional/ballistic shield aim overrides for crouch, prone and stand.
        local aiming = (layer == 1 or layer == 2 or not model.emplacement and
            (override == 2 or override == 17 or override == 30 or override == 39 or override == 44 or override == 59)) and
            mount_ready
        if not model.emplacement and (not model.throwable or state.config and state.config.throwable_aim_only) and not aiming then return nil, 'AIM_LAYER:' .. tostring(layer) end
        -- Layer10 handles reload/cocking; layers8/12/18 cover melee poses and strike/impact/recoil.
        local handling = animation_states and (not mount_ready or
            animation_states[11] ~= 199 and animation_states[11] ~= 585 or
            (animation_states[9] or 0) >= 315 and (animation_states[9] or 0) <= 322 or
            (animation_states[13] or 0) >= 35 and (animation_states[13] or 0) <= 76 or
            animation_states[19] == 4 or animation_states[19] == 20 or animation_states[19] == 32 or
            animation_states[19] == 42 or animation_states[19] == 46 or animation_states[19] == 62)
        if model.reload_states and sr.Unit.has_animation_state_machine(unit) then
            local states = {sr.Unit.animation_get_state(unit)}
            for layer, active in pairs(model.reload_states) do
                if active[states[layer+1]] then handling = true; break end
            end
        end
        local aim_target, pose, camera_pose
        if state.mount_target and state.config and state.config.counter_yaw and not handling then
            aim_target = state.mount_target
            if state.mount_weapon_root then
                local root = sr.Unit.world_position(unit, 1)
                if sr.Vector3.x(root) ~= state.mount_weapon_root[1] or sr.Vector3.y(root) ~= state.mount_weapon_root[2] or
                    sr.Vector3.z(root) ~= state.mount_weapon_root[3] then aim_target = nil end
            end
            if aim_target and type(read_native_aim) == 'function' then
                local ok, native = pcall(read_native_aim,sr,state)
                if not ok or type(native) ~= 'table' or native.status ~= 'FOUND' or not native.target or not native.pose then
                    return nil, 'NATIVE_AIM_UNAVAILABLE'
                end
                aim_target, pose = native.target, native.pose
            end
        elseif state.is_local ~= false and state.config and state.config.counter_yaw and
            not model.throwable and not model.emplacement and not handling then
            camera_pose = sr.World.debug_camera_pose(world)
            local camera = sr.Matrix4x4.forward(camera_pose)
            pose = sr.Unit.world_pose(unit, sr.Unit.node(unit, model.direction_node or model.muzzle))
            local muzzle = sr.Matrix4x4.forward(pose)
            local cx, cy = sr.Vector3.x(camera), sr.Vector3.y(camera)
            local mx, my = sr.Vector3.x(muzzle), sr.Vector3.y(muzzle)
            if cx*cx+cy*cy > 1e-16 and mx*mx+my*my > 1e-16 then
                local origin, right, root = sr.Matrix4x4.translation(camera_pose), sr.Matrix4x4.right(camera_pose),
                    sr.Unit.world_position(state.tp, 1)
                local rx, ry, rz = sr.Vector3.x(right), sr.Vector3.y(right), sr.Vector3.z(right)
                local lateral = ((sr.Vector3.x(origin)-sr.Vector3.x(root))*rx +
                    (sr.Vector3.y(origin)-sr.Vector3.y(root))*ry +
                    (sr.Vector3.z(origin)-sr.Vector3.z(root))*rz) / math.sqrt(rx*rx+ry*ry+rz*rz)
                -- Ballistic-shield aim still needs alignment when the camera is centered.
                if (math.abs(lateral) > .05 or model.one_handed and
                    (override == 17 or override == 39 or override == 59)) and
                    math.abs(lateral) < math.huge and mx*cx+my*cy > 0 then
                    local ok, native = pcall(read_native_aim, sr, state, position,
                        {sr.Vector3.x(muzzle), sr.Vector3.y(muzzle), sr.Vector3.z(muzzle)})
                    if not ok or type(native) ~= 'table' or native.status ~= 'FOUND' or not native.target then return nil, 'NATIVE_AIM_UNAVAILABLE' end
                    aim_target = native.target
                end
            end
        end
        if model.name == 'E/AT-12' and state.config and state.config.eat12_scope_line then
            assert(sr.Unit.has_node(unit, 'scope_arm_03'), 'missing scope lens node')
            pose = sr.Unit.world_pose(unit, sr.Unit.node(unit, model.muzzle))
            sr.Matrix4x4.set_translation(pose, sr.Matrix4x4.transform(
                sr.Unit.world_pose(unit, sr.Unit.node(unit, 'scope_arm_03')),
                sr.Vector3(-0.10634338855743408, 0.11887246370315552, -0.028735458850860596)))
        end
        if model.throwable then pose = sr.World.debug_camera_pose(world) end
        state.throw_speed_multiplier = 1
        if (model.throwable or model.exo_launcher) and type(read_armor) == 'function' then
            state.throw_speed_multiplier = read_armor(sr, session, state.player_goid, state.scope, dt)
        end
        local points, flight = sample(sr, unit, model, state.velocity, nil, nil, pose,
            state.throw_speed_multiplier, aim_target, state.exo_launch)
        assert(type(points) == 'table' and #points >= 2, 'guide points unavailable')
        if not state.line then
            assert(type(sr.World.destroy_line_object) == 'function', 'missing line cleanup')
            state.line = assert(sr.World.create_line_object(world, false))
        end
        state.compat_count, state.compat_num = 0, 0
        state.compat_draw_index = (state.compat_draw_index or 0) + 1
        if wants_dx11_gui(sr, state) and not state.compat_failed and sr.Gui and
            type(sr.Gui.rect) == 'function' and type(sr.World.create_screen_gui) == 'function' then
            local ok, worlds = pcall(sr.Application.worlds)
            local ui_world
            if ok and type(worlds) == 'table' then
                for _, candidate in ipairs(worlds) do
                    if candidate ~= world then ui_world = candidate; break end
                end
            end
            if ui_world and state.compat_world ~= ui_world then
                if state.compat_gui and state.compat_world then
                    pcall(sr.World.destroy_gui, state.compat_world, state.compat_gui)
                end
                state.compat_gui, state.compat_world = nil, ui_world
            end
            if ui_world and not state.compat_gui then
                local created, gui = pcall(sr.World.create_screen_gui, ui_world, 'scale', 1, 1, 'immediate')
                if created then state.compat_gui = gui else state.compat_failed = true end
            end
            if state.compat_gui then
                local posed, pose = pcall(sr.World.debug_camera_pose, world)
                state.compat_camera = posed and pose or nil
                local sized, width, height = pcall(sr.Gui.resolution)
                if not sized or type(width) ~= 'number' or type(height) ~= 'number' then
                    sized, width, height = pcall(sr.Application.back_buffer_size)
                end
                if sized and type(width) == 'number' and type(height) == 'number' and
                    width > 320 and height > 240 then
                    state.compat_width, state.compat_height = width, height
                    if not state.compat_fov then
                        state.compat_fov = 55
                        pcall(function()
                            local path = os.getenv('APPDATA') .. '/Arrowhead/Helldivers2/user_settings.config'
                            local file = io.open(path,'rb')
                            if file then
                                local config = file:read(65536) or ''
                                file:close()
                                local fov = tonumber(config:match('vertical_fov%s*=%s*(%d+)'))
                                if fov and fov >= 40 and fov <= 100 then state.compat_fov = fov end
                            end
                        end)
                    end
                end
            end
        end
        local ground_index, ground_fraction, ground_point, ground_surface, ground_contact
        if type(ground_hit) == 'function' then
            local ok, index, fraction, surface = pcall(ground_hit, sr, state, points)
            if ok and type(index) == 'number' and index >= 1 and index < #points and index % 1 == 0 and
                type(fraction) == 'number' and fraction >= 0 and fraction <= 1 then
                ground_index, ground_fraction, ground_point = index, fraction, {}
                ground_surface = surface
                ground_contact = type(surface) == 'table' and surface or {}
                for axis = 1, 3 do ground_point[axis] = points[index][axis]+fraction*(points[index+1][axis]-points[index][axis]) end
            elseif ok and state.ground_status == 'CLEAR' then
                ground_contact = false
            end
        end
        local color, white = sr.Color(255, unpack(state.config and state.config.line_color or {0, 255, 0})), sr.Color(255, 255, 255, 255)
        local first, helper_points, restored_start = 1
        if aiming and not model.exo_launcher and model.name ~= 'E/GL-21' and not (model.name == 'E/AT-12' and state.config and state.config.eat12_scope_line) and (state.occupant or
            state.is_local ~= false and state.fp ~= state.tp and rig == state.fp and ads_descending[model.name]) then
            camera_pose = camera_pose or sr.World.debug_camera_pose(world)
            local origin, forward = sr.Matrix4x4.translation(camera_pose), sr.Matrix4x4.forward(camera_pose)
            local ox, oy, oz = sr.Vector3.x(origin), sr.Vector3.y(origin), sr.Vector3.z(origin)
            local fx, fy, fz = sr.Vector3.x(forward), sr.Vector3.y(forward), sr.Vector3.z(forward)
            local peak, highest, near, far = nil, -math.huge, nil, nil
            for i = 1, ground_index and ground_index+1 or #points do
                local point = ground_index and i > ground_index and ground_point or points[i]
                local depth = (point[1]-ox)*fx + (point[2]-oy)*fy + (point[3]-oz)*fz
                if depth > 1e-6 then
                    near, far = near or i, i
                    -- Projected gravity-up height differs from this ratio only by a constant.
                    local height = (point[3]-oz)/depth
                    if height >= highest then peak, highest = i, height end
                end
            end
            if peak and peak > near and peak < far then first = peak end
            -- Trim only a valid above-hit fold within the collision path.
            if first > 1 and ground_index then
                local depth = (ground_point[1]-ox)*fx+(ground_point[2]-oy)*fy+(ground_point[3]-oz)*fz
                if depth > 1e-6 then
                    for i = first, ground_index-(ground_fraction == 0 and 1 or 0) do
                        local point = points[i]
                        local point_depth = (point[1]-ox)*fx+(point[2]-oy)*fy+(point[3]-oz)*fz
                        local height = (point[3]-oz)*depth-(ground_point[3]-oz)*point_depth
                        if point_depth <= 1e-6 or height <= 0 then
                            first = 1; break
                        end
                    end
                else first = 1 end
            end
            if ground_index then
                peak = first -- Keep the validated landing-tail start for helper sizing.
                local right, up = sr.Matrix4x4.right(camera_pose), sr.Matrix4x4.up(camera_pose)
                local rx, ry, rz = sr.Vector3.x(right), sr.Vector3.y(right), sr.Vector3.z(right)
                local ux, uy, uz = sr.Vector3.x(up), sr.Vector3.y(up), sr.Vector3.z(up)
                local function project(x, y, z)
                    x, y, z = x-ox, y-oy, z-oz
                    local depth = x*fx+y*fy+z*fz
                    if depth > 1e-6 and depth < math.huge then
                        local a, b = (x*rx+y*ry+z*rz)/depth, (x*ux+y*uy+z*uz)/depth
                        if a > -math.huge and a < math.huge and b > -math.huge and b < math.huge then return a, b, depth end
                    end
                end
                local ax, ay, hit_depth = project(unpack(ground_point))
                if first > 1 and ax then
                    local bx, by = project(ground_point[1], ground_point[2], ground_point[3]+.1)
                    local span, previous_x, previous_y = 0, ax, ay
                    for i = ground_index, first, -1 do
                        local x, y = project(unpack(points[i]))
                        if not x then span = math.huge; break end
                        span = span+math.sqrt((x-previous_x)^2+(y-previous_y)^2)
                        previous_x, previous_y = x, y
                    end
                    if bx and span < math.sqrt((bx-ax)^2+(by-ay)^2)-1e-10 then
                        first, peak = 1, nil
                    end
                end
                local bx, by = project(ground_point[1], ground_point[2], ground_point[3]+.5)
                local reference = ax and bx and math.sqrt((bx-ax)^2+(by-ay)^2)
                if peak and reference and reference > 1e-8 and reference < math.huge then
                    local span, previous_x, previous_y = 0, ax, ay
                    for i = ground_index, peak, -1 do
                        local x, y = project(unpack(points[i]))
                        if not x then span = reference; break end
                        span = span+math.sqrt((x-previous_x)^2+(y-previous_y)^2)
                        if span >= reference then break end
                        previous_x, previous_y = x, y
                    end
                    if span < reference then
                        local dx, dy = position[1]-ground_point[1], position[2]-ground_point[2]
                        local length = math.sqrt(dx*dx+dy*dy)
                        if length <= 1e-8 then dx, dy = -fx, -fy; length = math.sqrt(dx*dx+dy*dy) end
                        if length > 1e-8 and length < math.huge then
                            dx, dy = dx/length, dy/length
                            helper_points = {{0, 0, 0}}
                            local low, high = 0, math.huge
                            -- Cache the 60-degree shape; scale its projected length to the 50 cm reference.
                            for i = 1, 12 do
                                local angle = i*math.pi/36
                                local x, y, z = (1-math.cos(angle))*dx, (1-math.cos(angle))*dy, math.sin(angle)
                                helper_points[i+1] = {x, y, z}
                                local depth = x*fx+y*fy+z*fz
                                if depth < 0 then high = math.min(high, (hit_depth-1e-6)/-depth) end
                            end
                            local endpoint = helper_points[#helper_points]
                            local depth = endpoint[1]*fx+endpoint[2]*fy+endpoint[3]*fz
                            local chord = math.sqrt((endpoint[1]*rx+endpoint[2]*ry+endpoint[3]*rz-ax*depth)^2+
                                (endpoint[1]*ux+endpoint[2]*uy+endpoint[3]*uz-ay*depth)^2)
                            local radius = reference*hit_depth/(chord-reference*depth)
                            if not (radius > 0 and radius < high) then radius = math.min(1.5/math.pi, high*.5) end
                            for iteration = 1, 12 do
                                local length, slope, previous_dx, previous_dy = 0, 0, 0, 0
                                previous_x, previous_y = ax, ay
                                for i = 2, #helper_points do
                                    local point = helper_points[i]
                                    local x, y, depth = project(ground_point[1]+radius*point[1],
                                        ground_point[2]+radius*point[2], ground_point[3]+radius*point[3])
                                    if not x then helper_points = nil; break end
                                    local derivative_x, derivative_y = (x-ax)*hit_depth/(radius*depth), (y-ay)*hit_depth/(radius*depth)
                                    local segment = math.sqrt((x-previous_x)^2+(y-previous_y)^2)
                                    if segment > 1e-12 then
                                        slope = slope+((x-previous_x)*(derivative_x-previous_dx)+
                                            (y-previous_y)*(derivative_y-previous_dy))/segment
                                    end
                                    length = length+segment
                                    previous_x, previous_y, previous_dx, previous_dy = x, y, derivative_x, derivative_y
                                end
                                if not helper_points then break end
                                if math.abs(length-reference) <= reference*1e-7 or iteration == 12 then
                                    for i, point in ipairs(helper_points) do
                                        helper_points[i] = sr.Vector3(ground_point[1]+radius*point[1],
                                            ground_point[2]+radius*point[2], ground_point[3]+radius*point[3])
                                    end
                                    reference = length*.5
                                    break
                                end
                                if length < reference then low = radius else high = radius end
                                local next_radius = radius+(reference-length)/slope
                                radius = next_radius > low and next_radius < high and next_radius or
                                    (high < math.huge and (low+high)*.5 or radius*2)
                            end
                            previous_x, previous_y = project(unpack(points[first]))
                            while helper_points and first > 1 and span < reference do
                                local a, b = points[first], points[first-1]
                                local x, y = project(unpack(b))
                                if not x then break end
                                local segment = math.sqrt((x-previous_x)^2+(y-previous_y)^2)
                                if span+segment > reference then
                                    local fraction, depth = (reference-span)/segment, (a[1]-ox)*fx+(a[2]-oy)*fy+(a[3]-oz)*fz
                                    -- Convert the screen fraction back to the sampled 3D segment.
                                    fraction = fraction*depth/((1-fraction)*((b[1]-ox)*fx+(b[2]-oy)*fy+(b[3]-oz)*fz)+fraction*depth)
                                    restored_start = {}
                                    for axis = 1, 3 do restored_start[axis] = a[axis]+fraction*(b[axis]-a[axis]) end
                                end
                                span = span+segment
                                first, previous_x, previous_y = first-1, x, y
                            end
                        end
                    end
                end
            end
        end
        if first == #points or ground_index and ground_index < first then hide(sr, state) end
        local safety_orange = model.throwable and model.damage_radius_m and model.damage_radius_m > 0 and sr.Color(255, 255, 103, 0)
        local end_color = color
        for i = first, ground_index or #points - 1 do
            local a, b = i == first and restored_start or points[i], i == ground_index and ground_point or points[i + 1]
            local enter, leave = 0, 0
            if safety_orange then
                -- Split at the damage sphere around this frame's avatar root, including re-entry.
                local x, y, z = a[1]-motion_position[1], a[2]-motion_position[2], a[3]-motion_position[3]
                local dx, dy, dz = b[1]-a[1], b[2]-a[2], b[3]-a[3]
                local length2, dot = dx*dx+dy*dy+dz*dz, x*dx+y*dy+z*dz
                local discriminant = dot*dot-length2*(x*x+y*y+z*z-model.damage_radius_m^2)
                if length2 > 1e-12 and discriminant > 0 then
                    discriminant = math.sqrt(discriminant)
                    enter, leave = math.max(0, (-dot-discriminant)/length2), math.min(1, (-dot+discriminant)/length2)
                end
            end
            if enter < leave then
                local segment_color = flight and flight.fuse_index and i < flight.fuse_index and white or color
                local start = sr.Vector3(a[1]+enter*(b[1]-a[1]), a[2]+enter*(b[2]-a[2]), a[3]+enter*(b[3]-a[3]))
                local finish = sr.Vector3(a[1]+leave*(b[1]-a[1]), a[2]+leave*(b[2]-a[2]), a[3]+leave*(b[3]-a[3]))
                if enter > 0 then add_compat_line(sr, state, 'line', segment_color, sr.Vector3(unpack(a)), start) end
                add_compat_line(sr, state, 'line', safety_orange, start, finish)
                if leave < 1 then add_compat_line(sr, state, 'line', segment_color, finish, sr.Vector3(unpack(b))) end
                end_color = leave < 1 and segment_color or safety_orange
            else
                if a[1] ~= b[1] or a[2] ~= b[2] or a[3] ~= b[3] then
                    end_color = flight and flight.fuse_index and i < flight.fuse_index and white or color
                end
                add_compat_line(sr, state, 'line', flight and flight.fuse_index and i < flight.fuse_index and white or color,
                    sr.Vector3(unpack(a)), sr.Vector3(unpack(b)))
            end
        end
        if ground_index then
            draw_surface_hit(sr, state, ground_surface, end_color)
            if helper_points then
                for i = 2, #helper_points do
                    add_compat_line(sr, state, 'line', end_color, helper_points[i-1], helper_points[i])
                end
            end
            if state.config and state.config.damage_ring and model.damage_radius_m and model.damage_radius_m > 0 then
                draw_surface_hit(sr, state, ground_surface, color, model.damage_radius_m)
                if state.config.damage_ring == 's' then
                    state.damage_volume = {position=ground_surface.position, radius_m=model.damage_radius_m, color=state.config.line_color or {0,255,0}}
                else
                    draw_surface_hit(sr, state, ground_surface, color, model.damage_radius_m, true)
                end
            end
        end
        if flight and #flight.expiry > 0 then
            camera_pose = camera_pose or sr.World.debug_camera_pose(world)
            local right, up, forward, origin = sr.Matrix4x4.right(camera_pose), sr.Matrix4x4.up(camera_pose),
                sr.Matrix4x4.forward(camera_pose), sr.Matrix4x4.translation(camera_pose)
            local rx, ry, rz = sr.Vector3.x(right), sr.Vector3.y(right), sr.Vector3.z(right)
            local ux, uy, uz = sr.Vector3.x(up), sr.Vector3.y(up), sr.Vector3.z(up)
            local fz = sr.Vector3.z(forward)
            for _, endpoint in ipairs(flight.expiry) do
                local visible = first == 1
                if ground_index or not visible and first < #points then
                    visible = false
                    for i = first+(restored_start and 1 or 0), ground_index and ground_index+(ground_fraction == 1 and 1 or 0) or #points do
                        if points[i] == endpoint then visible = true; break end
                    end
                end
                local dx, dy, dz = endpoint[1]-sr.Vector3.x(origin), endpoint[2]-sr.Vector3.y(origin), endpoint[3]-sr.Vector3.z(origin)
                local depth = dx*sr.Vector3.x(forward)+dy*sr.Vector3.y(forward)+dz*fz
                if visible and depth > 1e-6 then
                    for sign = -1, 1, 2 do
                        local x, y, z = .005*depth*(rx+sign*ux), .005*depth*(ry+sign*uy), .005*depth*(rz+sign*uz)
                        add_compat_line(sr, state, 'line', color,
                            sr.Vector3(endpoint[1]-x, endpoint[2]-y, endpoint[3]-z),
                            sr.Vector3(endpoint[1]+x, endpoint[2]+y, endpoint[3]+z))
                    end
                    local height = endpoint[3]-flight.reference_z
                    local projection = math.sqrt((rz*depth-fz*(dx*rx+dy*ry+dz*rz))^2+(uz*depth-fz*(dx*ux+dy*uy+dz*uz))^2)
                    if height > 1e-8 and projection > 1e-8 and (not state.config or state.config.drop_line ~= false) then
                        if type(ground_hit) == 'function' then
                            local ok, index, fraction, surface = pcall(ground_hit, sr, state,
                                {endpoint, {endpoint[1], endpoint[2], flight.reference_z}}, true)
                            if ok and index == 1 and type(fraction) == 'number' and fraction >= 0 and fraction <= 1 then
                                height = height*fraction
                                draw_surface_hit(sr, state, surface, color)
                            end
                        end
                        local far_depth = depth-height*fz
                        local span = far_depth > 0 and height*projection/(depth*far_depth) or math.huge
                        -- Equal projected dash/gap lengths; bound work when the drop crosses the camera plane.
                        for i = 0, math.min(math.ceil(span/.04)-1, 511) do
                            local a, b = i*.04, math.min(i*.04+.02, span)
                            a, b = a*depth*depth/(projection+a*depth*fz), b*depth*depth/(projection+b*depth*fz)
                            add_compat_line(sr, state, 'line', color,
                                sr.Vector3(endpoint[1], endpoint[2], endpoint[3]-a),
                                sr.Vector3(endpoint[1], endpoint[2], math.max(endpoint[3]-height, endpoint[3]-b)))
                        end
                    end
                end
            end
        end
        if contact and state.config and state.config.red_cross then
            local ok, hit, index = pcall(contact, sr, world, session, points, dt, ground_contact)
            if ok and hit then
                hit, index = ground_point or hit, ground_index or index
                local pose = sr.World.debug_camera_pose(world)
                -- Move only the cross back along the guide; preserve the actual contact.
                local remaining = 1
                for i = index, 1, -1 do
                    local point = points[i]
                    local dx, dy, dz = point[1]-hit[1], point[2]-hit[2], point[3]-hit[3]
                    local length = math.sqrt(dx*dx+dy*dy+dz*dz)
                    if length >= remaining then
                        local scale = remaining/length
                        hit = {hit[1]+dx*scale, hit[2]+dy*scale, hit[3]+dz*scale}
                        break
                    end
                    remaining, hit = remaining-length, point
                end
                for _, axis in ipairs({'right', 'up'}) do
                    local direction = sr.Matrix4x4[axis](pose)
                    local x, y, z = .15*sr.Vector3.x(direction), .15*sr.Vector3.y(direction), .15*sr.Vector3.z(direction)
                    add_compat_line(sr, state, 'line', sr.Color(255, 255, 0, 0),
                        sr.Vector3(hit[1]-x, hit[2]-y, hit[3]-z), sr.Vector3(hit[1]+x, hit[2]+y, hit[3]+z))
                end
            end
        end
        sr.LineObject.dispatch(world, state.line)
        if state.hit_line then
            local point = sr.Vector3(0, 0, 0)
            add_compat_line(sr, state, 'hit_line', sr.Color(0, 0, 0, 0), point, point)
            sr.LineObject.dispatch(world, state.hit_line)
        end
        compat_flush(sr, state)
        return true, 'DRAWN'
    end

    local function tick(sr, state, dt)
        if coordinated then
            for _, key in ipairs({'line', 'hit_line'}) do
                if state[key] and live(sr, state) then sr.LineObject.reset(state[key]) end
            end
        else
            local ok, reason = resolve(sr, state, dt)
            if not ok then return nil, reason end
        end
        return render(sr, state, dt)
    end

    local tick_squad
    local function clear_motion(state)
        state.position, state.velocity = nil, nil
        if state.players then
            for _, player in pairs(state.players) do player.position, player.velocity = nil, nil end
        end
    end

    local function protected(sr, callback, state, ...)
        if not sr or not sr.Script or type(sr.Script.temp_byte_count) ~= 'function' or
            type(sr.Script.set_temp_byte_count) ~= 'function' then clear_motion(state); return end
        local counted, saved = pcall(sr.Script.temp_byte_count)
        if not counted then clear_motion(state); return end
        local ok, drawn, reason = pcall(callback, sr, state, ...)
        if not ok then
            clear_motion(state)
            reason = 'ERROR:' .. tostring(drawn)
        end
        if callback == tick then
            if ok and drawn then
                state.guide_visible = true
            else
                if state.guide_visible then pcall(hide, sr, state) end
                state.guide_visible = false
            end
        end
        if callback == tick_squad and not ok then
            for _, player in pairs(state.players) do
                player.session = state.session
                player.config, player.config_status, player.is_local = state.config, state.config_status, player.tp == state.local_tp
                pcall(hide, sr, player)
            end
        end
        if not pcall(sr.Script.set_temp_byte_count, saved) then clear_motion(state) end
        return ok, drawn, reason
    end

    tick_squad = function(sr, state, dt)
        state.frame = state.frame + 1
        state.session = nil
        local world, session = sr.Application.main_world(), sr.Network.game_session()
        local world_changed = state.world ~= world
        if world_changed then state.config_loaded = nil end
        state.session = session
        local session_ready = session and (not sr.GameSession or type(sr.GameSession.in_session) ~= 'function' or
            sr.GameSession.in_session(session) == true)
        state.world = world
        local world_live = world and live(sr, state)
        local ready = world_live and session_ready or false
        if world_changed or state.ready ~= ready then
            state.scope, state.ready, state.members, state.emplacements, state.elapsed = state.scope + 1, ready, {}, {}, 1
        end
        if ready then
            if not state.config_loaded and type(read_config) == 'function' then
                state.config, state.config_status = read_config(1)
                state.draw_all = state.config.scope == 'squad'
                state.config_loaded = true
            end
            state.elapsed = state.elapsed + (type(dt) == 'number' and dt > 0 and dt < math.huge and dt or 1 / 60)
            if state.elapsed >= 1 then
                local members = {}
                for _, unit in pairs(sr.World.units_by_resource(world,
                    'content/fac_helldivers/cha_avatar/avatar_helldiver') or {}) do members[unit] = true end
                state.members, state.elapsed = members, 0
                state.emplacements = {}
                for _, model in ipairs(catalog or {}) do
                    if model.emplacement then
                        for _, unit in pairs(sr.World.units_by_resource(world, model.resource) or {}) do
                            state.emplacements[unit] = model
                        end
                    end
                end
            end
        else
            state.members, state.emplacements, state.elapsed = {}, {}, 1
        end
        local active, binding_reason, local_tp, player_goid = {}
        if ready and type(resolve_local) == 'function' then
            local resolved
            resolved, local_tp, binding_reason, player_goid = pcall(resolve_local, sr, state, state.members, dt)
            if not resolved and not next(state.emplacements or {}) then error(local_tp, 0) end
            if not resolved then binding_reason, local_tp = 'ERROR:' .. tostring(local_tp), nil end
        end
        for unit in pairs(state.members) do
            if state.draw_all or unit == local_tp then active[unit] = true end
        end
        for unit in pairs(state.emplacements or {}) do active[unit] = true end
        if local_tp and (state.local_tp ~= local_tp or state.elapsed == 0) then
            state.fp = unique(sr, state, 'content/fac_helldivers/fp_cha_avatar/fp_cha_avatar')
        elseif not local_tp then state.fp = nil end
        state.local_tp = local_tp
        local occupants = {}
        if ready and type(read_emplacement) == 'function' and state.config and state.config.enabled and
            type(dt) == 'number' and dt > 0 and dt < math.huge then
            for _, model in pairs(state.emplacements or {}) do
                if (model.name == 'E/AT-12' or model.name == 'E/GL-21') and state.config.weapons[model.name] ~= false then
                    for avatar in pairs(state.members) do
                        if (avatar == local_tp or state.draw_all) and sr.Unit.alive(avatar) then
                            local ok, row, unit = pcall(read_emplacement,sr,state,avatar)
                            local occupied_model = unit and state.emplacements[unit]
                            if ok and row and row.status == 'ok' and occupied_model and
                                (occupied_model.name == 'E/AT-12' or occupied_model.name == 'E/GL-21') then
                                if occupants[unit] ~= nil then occupants[unit] = false else occupants[unit] = avatar end
                            end
                        end
                    end
                    break
                end
            end
        end
        local mounted, mount_target, mount_weapon_root, mount_weapon_entity_ref, mount_controller_entity_ref, mount_launch
        if ready and local_tp and sr.Unit.alive(local_tp) and type(read_emplacement) == 'function' and
            type(dt) == 'number' and dt > 0 and dt < math.huge and state.config and state.config.enabled then
            for _, model in pairs(state.emplacements or {}) do
                if (model.name == 'E/AT-12' or model.name == 'E/GL-21' or model.exo_launcher) and state.config.weapons[model.name] ~= false then
                    local ok, row = pcall(read_emplacement, sr, state)
                    if ok and row and row.status == 'ok' then
                        local root = sr.Unit.world_position(local_tp, 1)
                        if sr.Vector3.x(root) == row.avatar.root[1] and sr.Vector3.y(root) == row.avatar.root[2] and
                            sr.Vector3.z(root) == row.avatar.root[3] then
                            -- Native and Lua roots match exactly; ambiguous colocated mounts stay unbound.
                            for candidate, model in pairs(state.emplacements) do
